fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as stated in the problem):
    // start + sub.len() <= main.len()
    if start > main.len() || main.len().saturating_sub(start) < sub.len() {
        return false; // defensive, keeps behavior well-defined even if precondition is violated
    }

    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty sub is always a subarray.
    if sub.is_empty() {
        return true;
    }
    // If sub is longer than main, it cannot fit.
    if sub.len() > main.len() {
        return false;
    }

    let max_start = main.len() - sub.len();
    for start in 0..=max_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}